import {effectTagEditor} from './effect-tag-editor.js';
import {validTimeline} from './blueprint-model.js';
import {effectAtLevel} from './effect-scaling.js';
export function effectScalingEditor(document,doc,index,files,hooks,edit){
 const row=doc.data.modifiers[index],root=document.createElement('div');root.className='effect-scaling-editor';root.dataset.effectScaling=String(index);
 const make=(tag,text)=>{const e=document.createElement(tag);if(text)e.textContent=text;return e;},field=(name,control)=>{const label=make('label',name);control.setAttribute('aria-label',name);label.append(control);root.append(label);};
 const source=make('select');source.dataset.effectMagnitudeSource='';for(const[value,text]of [['','상수'],['source','출처 속성'],['target','대상 속성'],['parameter','호출 인자']]){const option=make('option',text);option.value=value;source.append(option);}source.value=row.magnitudeSource?.owner||row.magnitudeSource?.type||'';field('계산 입력',source);
 source.onchange=()=>edit(data=>{const value=source.value;data.modifiers[index].magnitudeSource=value==='parameter'?{type:'parameter',name:'Damage',default:1}:value?{type:'attribute',owner:value,attribute:'Health',basis:'current'}:undefined;if(!value)delete data.modifiers[index].magnitudeSource;});
 if(row.magnitudeSource){const input=row.magnitudeSource,name=make('input');name.value=input.name||input.attribute;name.maxLength=80;name.dataset.effectInputName='';field(input.type==='parameter'?'인자 이름':'캡처 속성',name);name.onchange=()=>edit(data=>data.modifiers[index].magnitudeSource[input.type==='parameter'?'name':'attribute']=name.value);
  if(input.type==='attribute'){const basis=make('select');for(const[value,text]of [['current','현재값'],['base','기본값']]){const option=make('option',text);option.value=value;basis.append(option);}basis.value=input.basis;field('속성 값',basis);basis.onchange=()=>edit(data=>data.modifiers[index].magnitudeSource.basis=basis.value);const fixed=make('input');fixed.type='checkbox';fixed.checked=input.snapshot!==false;fixed.dataset.effectSnapshot='';field('적용 시 고정',fixed);fixed.onchange=()=>edit(data=>{const source=data.modifiers[index].magnitudeSource;if(fixed.checked)delete source.snapshot;else source.snapshot=false;});}
  else{const fallback=make('input');fallback.type='number';fallback.step='any';fallback.value=input.default??'';fallback.placeholder='필수';field('누락 시 기본값',fallback);fallback.onchange=()=>edit(data=>{const value=data.modifiers[index].magnitudeSource;if(fallback.value==='')delete value.default;else value.default=Number(fallback.value);});}
 }
 const curve=make('select');curve.dataset.effectCurve='';for(const f of[{path:'',name:'없음'},...files.filter(f=>f.kind==='curve'),...(row.scaling?.curve&&!files.some(f=>f.path===row.scaling.curve)?[{path:row.scaling.curve,name:row.scaling.curve}]:[])]){const option=make('option',f.name);option.value=f.path;curve.append(option);}curve.value=row.scaling?.curve||'';field('레벨 커브',curve);
 curve.onchange=async()=>{const path=curve.value,before=JSON.stringify(doc.data);if(!path){edit(data=>delete data.modifiers[index].scaling);return;}try{const data=await hooks.readAsset(path);if(!curve.isConnected||curve.value!==path||JSON.stringify(doc.data)!==before)return;const track=data?.timeline?.tracks.find(t=>t.type==='float');if(!validTimeline(data.timeline)||!track)throw Error('실수 트랙이 있는 커브를 선택하세요.');edit(data=>data.modifiers[index].scaling={curve:path,track:track.id});}catch(error){hooks.error(error.message);if(curve.isConnected)curve.value=row.scaling?.curve||'';}};
 const track=make('select');track.dataset.effectCurveTrack='';if(row.scaling){const option=make('option',row.scaling.track);option.value=row.scaling.track;track.append(option);track.value=row.scaling.track;track.onchange=()=>edit(data=>data.modifiers[index].scaling.track=track.value);field('실수 트랙',track);const open=make('button','커브 열기');open.type='button';open.onclick=()=>hooks.openAsset?.(row.scaling.curve);root.append(open);}
 const preview=make('div');preview.className='effect-scaling-preview';const level=make('input'),label=make('label','미리보기 레벨'),output=make('output');level.type='number';level.min='0';level.max='1000000000';level.step='any';level.value=doc.view?.effectPreviewLevel??1;level.dataset.effectPreviewLevel='';level.setAttribute('aria-label','효과 미리보기 레벨');output.dataset.effectPreviewValue='';label.append(level);preview.append(label,output);root.append(preview);let asset;
 const previewRoles=['source','target','instigator','causer'];if(row.tagRequirements){for(const role of previewRoles){const text=make('input'),label=make('label',({source:'출처',target:'대상',instigator:'발동자',causer:'원인'})[role]+' 미리보기 태그');text.value=doc.view?.effectPreviewTags?.[role]||'';text.dataset.effectPreviewTags=role;label.append(text);preview.prepend(label);text.oninput=()=>{((doc.view??={}).effectPreviewTags??={})[role]=text.value;update();};}}
 const inputPreview=make('input');if(row.magnitudeSource){inputPreview.type='number';inputPreview.step='any';inputPreview.value=doc.view?.effectInputPreview?.[index]??row.magnitudeSource.default??1;inputPreview.dataset.effectInputPreview='';const label=make('label','미리보기 입력');label.append(inputPreview);preview.prepend(label);inputPreview.oninput=()=>{((doc.view??={}).effectInputPreview??={})[index]=Number(inputPreview.value);update();};}
 const update=()=>{try{const value=Number(level.value);if(!Number.isFinite(value)||value<0||value>1e9)throw Error('레벨 범위를 확인하세요.');const number=Number(inputPreview.value),context={application:Object.fromEntries(previewRoles.map(role=>[role+'Tags',(doc.view?.effectPreviewTags?.[role]||'').split(',').map(t=>t.trim()).filter(Boolean)])),...(row.magnitudeSource?{attributes:[number],parameters:{[row.magnitudeSource.name]:number}}:{})};const resolved=effectAtLevel({data:{...doc.data,modifiers:[row]},curves:asset&&row.scaling?{[row.scaling.curve]:asset}:{}},value,context).modifiers[0];output.textContent=resolved.qualified===false?'조건 불일치':String(Number(resolved.magnitude.toPrecision(7)));output.title='';}catch(error){output.textContent='—';output.title=error.message;}};
 root.hbEffectPreviewLevel=value=>{level.value=value;update();};level.oninput=()=>{const value=Number(level.value);(doc.view??={}).effectPreviewLevel=value;for(const other of root.closest('.asset-form')?.querySelectorAll('[data-effect-scaling]')||[])other.hbEffectPreviewLevel?.(value);};update();
 if(row.scaling){const before=JSON.stringify(doc.data);Promise.resolve().then(()=>hooks.readAsset(row.scaling.curve)).then(data=>{if(!root.isConnected||JSON.stringify(doc.data)!==before)return;if(!validTimeline(data?.timeline))throw Error('커브 정의를 확인하세요.');asset=data;track.replaceChildren();for(const t of data.timeline.tracks.filter(t=>t.type==='float')){const option=make('option',t.name||t.id);option.value=t.id;track.append(option);}track.value=row.scaling.track;update();}).catch(error=>{if(root.isConnected){output.textContent='—';output.title=error.message;}});}
 root.append(effectTagEditor(document,doc,index,edit));
 return root;
}
